#!/bin/bash
# Installs Sketch into Claude Code by generating agents and skills under ~/.claude.
#
#   install.sh             install or update
#   install.sh uninstall   remove only what this script generated
#
# The generated files carry a marker line. The script refuses to overwrite a file
# without that marker, so it never touches anything you wrote yourself.
# It does not edit your settings.json. See settings.snippet.json and README.md.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
CORE="$ROOT/core"
LIST="$ROOT/adapters/claude-code/agents.list"
DEST="${CLAUDE_HOME:-$HOME/.claude}"
# a filled-in copy of all of core/, so every {{CORE}}/... reference opens a file
# whose own references are already resolved
CORE_OUT="$DEST/sketch/core"
[ -f "$ROOT/VERSION" ] || { echo "STOPPED: $ROOT/VERSION is missing" >&2; exit 1; }
VERSION="$(tr -d '[:space:]' < "$ROOT/VERSION")"
MARK="<!-- generated by sketch adapters/claude-code/install.sh (sketch $VERSION). Edit core/ in the Sketch repo and rerun the script. -->"
MARK_KEY='generated by sketch adapters/claude-code/install.sh'

fail() { echo "STOPPED: $*" >&2; exit 1; }

# true when the file does not exist yet, or was generated by this script
may_write() { [ ! -e "$1" ] || grep -qF -- "$MARK_KEY" "$1"; }
# true only when the file exists and was generated by this script
is_ours() { [ -f "$1" ] && grep -qF -- "$MARK_KEY" "$1"; }

# expand SRC DST [TOOLS MODEL]: fill {{CORE}}, {{CORE_SOURCE}} and {{VERSION}}, add the marker
# (after the frontmatter if there is one, else on top), and tools/model when given
expand() {
  awk -v mark="$MARK" -v core="$CORE_OUT" -v src_core="$CORE" -v version="$VERSION" -v tools="${3:-}" -v model="${4:-}" '
    NR == 1 && $0 != "---" { print mark; fm = -1 }
    NR == 1 && $0 == "---" { fm = 1; print; next }
    fm == 1 && $0 == "---" {
      if (tools != "") print "tools: " tools
      if (model != "") print "model: " model
      print; print mark; fm = -1; next
    }
    { gsub(/\{\{CORE\}\}/, core); gsub(/\{\{CORE_SOURCE\}\}/, src_core); gsub(/\{\{VERSION\}\}/, version); print }
  ' "$1" > "$2"
}

[ -d "$CORE/agents" ] && [ -d "$CORE/skills" ] || fail "core/agents or core/skills is missing under $ROOT"
[ -f "$LIST" ] || fail "$LIST is missing"

if [ "${1:-}" = "uninstall" ]; then
  while IFS='|' read -r name tools model; do
    case "$name" in ''|\#*) continue ;; esac
    if is_ours "$DEST/agents/$name.md"; then rm "$DEST/agents/$name.md"; echo "removed agent $name"; fi
  done < "$LIST"
  for d in "$CORE"/skills/*/; do
    name="$(basename "$d")"
    if is_ours "$DEST/skills/$name/SKILL.md"; then
      rm "$DEST/skills/$name/SKILL.md"
      rmdir "$DEST/skills/$name" 2>/dev/null || true
      echo "removed skill $name"
    fi
  done
  if [ -d "$CORE_OUT" ]; then
    find "$CORE_OUT" -type f -name '*.md' | while read -r f; do
      if is_ours "$f"; then rm "$f"; fi
    done
    find "$DEST/sketch" -depth -type d -empty -delete 2>/dev/null || true
    echo "removed $CORE_OUT"
  fi
  exit 0
fi

# every agent file must be listed, so nothing is silently left out
for f in "$CORE"/agents/*.md; do
  n="$(basename "$f" .md)"
  grep -q "^${n}|" "$LIST" || fail "core/agents/$n.md is not listed in agents.list"
done

mkdir -p "$DEST/agents" "$DEST/skills" "$CORE_OUT"

# the filled-in copy of core/ that {{CORE}} points to
(cd "$CORE" && find . -type f -name '*.md') | while read -r rel; do
  dst="$CORE_OUT/${rel#./}"
  mkdir -p "$(dirname "$dst")"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away."
  expand "$CORE/${rel#./}" "$dst"
done
echo "core   $CORE_OUT"

# agents: add tools and model to the frontmatter, add the marker, fill the placeholders
while IFS='|' read -r name tools model; do
  case "$name" in ''|\#*) continue ;; esac
  src="$CORE/agents/$name.md"
  dst="$DEST/agents/$name.md"
  [ -f "$src" ] || fail "agents.list names '$name' but $src does not exist"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away or rename the agent."
  expand "$src" "$dst" "$tools" "$model"
  echo "agent  $name"
done < "$LIST"

# skills: add the marker, fill the placeholders
for d in "$CORE"/skills/*/; do
  name="$(basename "$d")"
  src="$d/SKILL.md"
  dst="$DEST/skills/$name/SKILL.md"
  [ -f "$src" ] || fail "$src does not exist"
  mkdir -p "$DEST/skills/$name"
  may_write "$dst" || fail "$dst exists and was not generated by this script. Move it away or rename the skill in core/skills."
  expand "$src" "$dst"
  echo "skill  $name"
done

echo "Installed sketch $VERSION into $DEST. Restart Claude Code (or start a new session) to pick them up."
echo "Permissions are not changed. See adapters/claude-code/settings.snippet.json."
